using System.Collections.Frozen;
using System.Runtime.InteropServices;

namespace CatalogSvc;

/// <summary>
/// Read-optimized product catalog. Call <see cref="Build"/> after adding all
/// products to freeze the lookup structures for maximum query throughput.
/// </summary>
public class ProductCatalog
{
    // Mutable builders used before Build() is called.
    private readonly Dictionary<string, string> _categoryBuilder = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, double> _priceBuilder = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, List<string>> _reverseCategoryBuilder = new(StringComparer.OrdinalIgnoreCase);

    // Frozen, read-optimized structures populated by Build().
    private FrozenDictionary<string, string> _categories = FrozenDictionary<string, string>.Empty;
    private FrozenDictionary<string, double> _prices = FrozenDictionary<string, double>.Empty;
    // Reverse index: category → product codes for O(1) category lookups.
    private FrozenDictionary<string, string[]> _productsByCategory = FrozenDictionary<string, string[]>.Empty;

    private bool _frozen;

    public void AddProduct(string code, string category, decimal price)
    {
        if (_frozen)
            throw new InvalidOperationException("Catalog is frozen. Cannot add products after Build().");

        _categoryBuilder[code] = category;
        _priceBuilder[code] = (double)price;

        ref var list = ref CollectionsMarshal.GetValueRefOrAddDefault(
            _reverseCategoryBuilder, category, out bool exists);
        if (!exists)
            list = new List<string>();
        list!.Add(code);
    }

    /// <summary>
    /// Freezes the catalog into read-optimized structures. Must be called
    /// once after all products are added and before querying.
    /// </summary>
    public void Build()
    {
        _categories = _categoryBuilder.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _prices = _priceBuilder.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _productsByCategory = _reverseCategoryBuilder.ToFrozenDictionary(
            kvp => kvp.Key,
            kvp => kvp.Value.ToArray(),
            StringComparer.OrdinalIgnoreCase);

        _categoryBuilder.Clear();
        _priceBuilder.Clear();
        _reverseCategoryBuilder.Clear();
        _frozen = true;
    }

    public string? GetCategory(string code)
        => _categories.TryGetValue(code, out var cat) ? cat : null;

    public double GetTotalPrice(ReadOnlySpan<string> codes)
    {
        double total = 0d;
        foreach (var code in codes)
        {
            if (_prices.TryGetValue(code, out var price))
                total += price;
        }
        return total;
    }

    public string[] GetProductsByCategory(string category)
        => _productsByCategory.TryGetValue(category, out var products) ? products : [];
}

